<?php
declare(strict_types=1);
if(session_status()!==PHP_SESSION_ACTIVE){session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])]);session_start();}
define('ROOT_PATH',dirname(__DIR__));define('DATA_PATH',ROOT_PATH.'/data');define('UPLOAD_PATH',ROOT_PATH.'/uploads/projects');define('BRANDING_UPLOAD_PATH',ROOT_PATH.'/uploads/branding');foreach([DATA_PATH,UPLOAD_PATH,BRANDING_UPLOAD_PATH] as $d)if(!is_dir($d))@mkdir($d,0775,true);
function e(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}function slugify(string $v):string{$v=strtolower(trim((string)preg_replace('/[^a-zA-Z0-9]+/','-',$v),'-'));return $v?:'item-'.time();}function csrf_token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}function verify_csrf():void{if(!isset($_POST['csrf'])||!hash_equals($_SESSION['csrf']??'',(string)$_POST['csrf'])){http_response_code(419);exit('Invalid request token.');}}function is_admin():bool{return !empty($_SESSION['admin']);}function require_admin():void{if(!is_admin()){header('Location:'.site_url('/admin/login.php'));exit;}}
function base_path():string{$docRoot=isset($_SERVER['DOCUMENT_ROOT'])?realpath((string)$_SERVER['DOCUMENT_ROOT']):false;$root=realpath(ROOT_PATH);if($docRoot&&$root){$docRoot=str_replace('\\','/',$docRoot);$root=str_replace('\\','/',$root);if(str_starts_with(strtolower($root),strtolower($docRoot))){$relative=trim(substr($root,strlen($docRoot)),'/');return $relative===''?'':'/'.$relative;}}$script=str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??'/'));$dir=rtrim(dirname($script),'/');if(str_ends_with($dir,'/admin'))$dir=substr($dir,0,-6);return $dir==='/'?'':$dir;}function site_url(string $path=''):string{$base=base_path();$path='/'.ltrim($path,'/');return ($base?:'').$path;}function asset_url(string $path):string{return site_url($path).'?v=20261002-6';}
function database_config():array{$d=['host'=>'127.0.0.1','port'=>3306,'database'=>'','username'=>'','password'=>'','charset'=>'utf8mb4'];$f=ROOT_PATH.'/config/database.php';$c=is_file($f)?require $f:[];return array_merge($d,is_array($c)?$c:[]);}function db():?PDO{static $pdo=false;if($pdo!==false)return $pdo?:null;$c=database_config();if(empty($c['database']))return $pdo=null;try{$pdo=new PDO('mysql:host='.$c['host'].';port='.(int)$c['port'].';dbname='.$c['database'].';charset='.$c['charset'],(string)$c['username'],(string)$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);db_schema($pdo);return $pdo;}catch(Throwable $e){error_log('DB: '.$e->getMessage());return $pdo=null;}}
function db_schema(PDO $p):void{$schema=ROOT_PATH.'/database/schema.sql';if(is_file($schema)){static $done=false;if(!$done){$done=true;$sql=(string)file_get_contents($schema);$sql=preg_replace('/^\s*(CREATE DATABASE|USE)\b.*?;\s*$/mi','',$sql);foreach(array_filter(array_map('trim',preg_split('/;\s*(?:\r?\n|$)/',$sql))) as $q){if(str_starts_with($q,'--'))$q=preg_replace('/^(?:--[^\n]*\n)+/','',$q);if(trim($q)!=='')try{$p->exec($q);}catch(Throwable $e){error_log('Schema: '.$e->getMessage());}}}}}
function site_setting(string $key,string $default=''):string{$p=db();if(!$p)return $default;try{$s=$p->prepare('SELECT setting_value FROM site_settings WHERE setting_key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:(string)$v;}catch(Throwable $e){return $default;}}function set_site_setting(string $key,string $value):bool{$p=db();if(!$p)return false;try{$s=$p->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');return $s->execute([$key,$value]);}catch(Throwable $e){return false;}}function branding_settings():array{return ['site_name'=>site_setting('site_name','Galindos Builders LLC'),'favicon_url'=>site_setting('favicon_url',''),'meta_image_url'=>site_setting('meta_image_url',''),'header_logo_url'=>site_setting('header_logo_url','')];}function save_branding_settings(array $b):bool{$ok=true;foreach(['site_name','favicon_url','meta_image_url','header_logo_url'] as $k)$ok=set_site_setting($k,(string)($b[$k]??''))&&$ok;return $ok;}function save_branding_image(array $f,bool $allowIco=false):?string{if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||empty($f['tmp_name'])||!is_uploaded_file($f['tmp_name'])||filesize($f['tmp_name'])>5*1024*1024)return null;$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif','image/svg+xml'=>'svg'];if($allowIco){$allowed['image/x-icon']='ico';$allowed['image/vnd.microsoft.icon']='ico';}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$mime]))return null;$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],BRANDING_UPLOAD_PATH.'/'.$name))return null;return site_url('/uploads/branding/'.$name);}
function legacy_read(string $f,array $fallback=[]):array{$path=DATA_PATH.'/'.$f;if(!is_file($path))return $fallback;$a=json_decode((string)file_get_contents($path),true);return is_array($a)?$a:$fallback;}
function admins():array{$p=db();if(!$p)return legacy_read('admins.json',[]);try{$r=$p->query('SELECT id,username,password_hash AS password,created_at FROM admins ORDER BY id')->fetchAll();if(!$r){$old=legacy_read('admins.json',[]);foreach($old as $a)admin_create((string)$a['username'],(string)$a['password'],true);return $old;}return $r;}catch(Throwable $e){return [];}}function admin_create(string $u,string $password,bool $alreadyHashed=false):bool{$p=db();if(!$p)return false;$hash=$alreadyHashed?$password:password_hash($password,PASSWORD_DEFAULT);try{$s=$p->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');return $s->execute([$u,$hash]);}catch(Throwable $e){return false;}}
function quote_submit(array $q):bool{$p=db();if(!$p)return false;try{$s=$p->prepare('INSERT INTO quote_submissions(name,email,phone,project_type,location,message,status) VALUES(?,?,?,?,?,?,?)');return $s->execute([$q['name']??'',$q['email']??'',$q['phone']??'',$q['project_type']??$q['project']??'',$q['location']??'',$q['message']??'','New']);}catch(Throwable $e){return false;}}function quotes():array{$p=db();if(!$p)return [];try{return $p->query('SELECT id,name,email,phone,project_type AS project,location,message,status,submitted_at AS created_at FROM quote_submissions ORDER BY submitted_at DESC')->fetchAll();}catch(Throwable $e){return [];}}function quote_set_status(int $id,string $status):bool{$p=db();if(!$p)return false;$allowed=['New','Contacted','Quoted','Won','Closed'];if(!in_array($status,$allowed,true))return false;$s=$p->prepare('UPDATE quote_submissions SET status=? WHERE id=?');return $s->execute([$status,$id]);}
function read_json(string $file,array $fallback=[]):array{$key=pathinfo($file,PATHINFO_FILENAME);if($key==='admins')return admins();if($key==='quotes')return quotes();$p=db();if(!$p)return legacy_read($file,$fallback);try{if($key==='home'){$s=$p->prepare('SELECT setting_value FROM site_settings WHERE setting_key=?');$s->execute(['home']);$v=$s->fetchColumn();if($v!==false)return json_decode($v,true)?:$fallback;}if($key==='services'){$r=$p->query('SELECT id,name,description,sort_order AS sort,visible FROM services ORDER BY sort_order,id')->fetchAll();if($r)return $r;}if($key==='tabs'){$r=$p->query('SELECT id,label,url,page_slug,visible,sort_order AS sort FROM navigation_tabs ORDER BY sort_order,id')->fetchAll();if($r)return $r;}if($key==='pages'){$r=$p->query('SELECT * FROM pages ORDER BY sort_order,title')->fetchAll();if($r)return $r;}if($key==='projects'){$r=$p->query('SELECT * FROM projects ORDER BY created_at')->fetchAll();if($r){$q=$p->prepare('SELECT image_url FROM project_images WHERE project_id=? ORDER BY sort_order,id');foreach($r as &$x){$q->execute([$x['id']]);$x['images']=$q->fetchAll(PDO::FETCH_COLUMN);$x['featured']=(bool)$x['featured'];}unset($x);return $r;}}if($key==='seo'){$o=[];foreach($p->query('SELECT * FROM seo_settings')->fetchAll() as $x)$o[$x['page_key']]=['title'=>$x['title'],'description'=>$x['description'],'keywords'=>$x['keywords']];if($o)return $o;}$s=$p->prepare('SELECT payload FROM site_store WHERE store_key=?');$s->execute([$key]);$v=$s->fetchColumn();if($v!==false)return json_decode($v,true)?:$fallback;$old=legacy_read($file,[]);if($old){write_json($file,$old);return $old;}}catch(Throwable $e){error_log('DB read '.$key.': '.$e->getMessage());}return $fallback;}
function write_json(string $file,array $data):bool{$key=pathinfo($file,PATHINFO_FILENAME);$p=db();if(!$p)return false;if($key==='quotes')return false;if($key==='admins'){if(!$data)return false;foreach($data as $a)if(!admin_create((string)$a['username'],(string)$a['password'],true))return false;return true;}try{$p->beginTransaction();if($key==='home'){$s=$p->prepare('INSERT INTO site_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$s->execute(['home',json_encode($data,JSON_UNESCAPED_SLASHES)]);}elseif($key==='services'){$p->exec('DELETE FROM services');$s=$p->prepare('INSERT INTO services(id,name,description,sort_order,visible) VALUES(?,?,?,?,?)');foreach($data as $i=>$x)$s->execute([$x['id']??slugify($x['name']??'service'),$x['name']??'',$x['description']??'',(int)($x['sort']??$i*10),isset($x['visible'])?(int)(bool)$x['visible']:1]);}elseif($key==='tabs'){$p->exec('DELETE FROM navigation_tabs');$s=$p->prepare('INSERT INTO navigation_tabs(id,label,url,page_slug,visible,sort_order) VALUES(?,?,?,?,?,?)');foreach($data as $x)$s->execute([$x['id'],$x['label'],$x['url']??'',$x['page_slug']??'',(int)!empty($x['visible']),(int)($x['sort']??50)]);}elseif($key==='pages'){$p->exec('DELETE FROM pages');$s=$p->prepare('INSERT INTO pages(id,slug,title,eyebrow,hero_text,content,cta_title,cta_text,cta_label,cta_url,seo_title,seo_description,sort_order,visible) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($data as $i=>$x)$s->execute([$x['id'],$x['slug'],$x['title'],$x['eyebrow']??'',$x['hero_text']??'',$x['content']??'',$x['cta_title']??'',$x['cta_text']??'',$x['cta_label']??'',$x['cta_url']??'',$x['seo_title']??'',$x['seo_description']??'',(int)($x['sort_order']??$i*10),isset($x['visible'])?(int)(bool)$x['visible']:1]);}elseif($key==='projects'){$p->exec('DELETE FROM project_images');$p->exec('DELETE FROM projects');$s=$p->prepare('INSERT INTO projects(id,slug,name,location,category,status,description,featured,sort_order,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$im=$p->prepare('INSERT INTO project_images(project_id,image_url,sort_order) VALUES(?,?,?)');foreach($data as $i=>$x){$created=!empty($x['created_at'])?date('Y-m-d H:i:s',strtotime($x['created_at'])):date('Y-m-d H:i:s');$s->execute([$x['id'],$x['slug'],$x['name'],$x['location']??'',$x['category']??'',$x['status']??'',$x['description']??'',(int)!empty($x['featured']),(int)($x['sort_order']??$i*10),$created]);foreach($x['images']??[] as $n=>$url)$im->execute([$x['id'],$url,$n]);}}elseif($key==='seo'){$p->exec('DELETE FROM seo_settings');$s=$p->prepare('INSERT INTO seo_settings(page_key,title,description,keywords) VALUES(?,?,?,?)');foreach($data as $k=>$x)$s->execute([$k,$x['title']??'',$x['description']??'',$x['keywords']??'']);}else{$s=$p->prepare('INSERT INTO site_store(store_key,payload) VALUES(?,?) ON DUPLICATE KEY UPDATE payload=VALUES(payload)');$s->execute([$key,json_encode($data,JSON_UNESCAPED_SLASHES)]);}$p->commit();return true;}catch(Throwable $e){if($p->inTransaction())$p->rollBack();error_log('DB write '.$key.': '.$e->getMessage());return false;}}
function default_home():array{return ['hero_eyebrow'=>'BUILT WITH PURPOSE','hero_title'=>'Craftsmanship that frames the future.','hero_text'=>'Professional framing and construction built around quality, safety, communication and dependable execution.','about_title'=>'Working together. Building it right.','about_text'=>'We bring a hands-on approach to every project, coordinating crews, schedules and details with one goal: deliver strong work our clients can count on.','contact_title'=>'Have a project in mind?','contact_text'=>'Tell us about the scope, schedule and location. We’ll get back to you to discuss the next steps.'];}function home_content():array{return array_merge(default_home(),read_json('home.json',[]));}function services():array{return read_json('services.json',[['id'=>'wood','name'=>'Wood Framing','description'=>'Structural framing for residential and commercial construction.'],['id'=>'construction','name'=>'Construction','description'=>'Reliable field execution with a focus on schedule, coordination and quality.'],['id'=>'support','name'=>'Project Support','description'=>'Experienced crews ready to support complex scopes and active jobsites.']]);}function seo(string $page='home'):array{$all=read_json('seo.json',[]);$d=['title'=>'Galindos Builders LLC | Framing & Construction','description'=>'Professional framing and construction services by Galindos Builders LLC.','keywords'=>'framing contractor, construction, Maryland'];return array_merge($d,$all[$page]??[]);}function tabs():array{$d=[['id'=>'projects','label'=>'Projects','url'=>site_url('/projects'),'visible'=>true,'sort'=>10,'page_slug'=>''],['id'=>'services','label'=>'Services','url'=>site_url('/#services'),'visible'=>true,'sort'=>20,'page_slug'=>''],['id'=>'about','label'=>'About','url'=>site_url('/#about'),'visible'=>true,'sort'=>30,'page_slug'=>''],['id'=>'contact','label'=>'Contact','url'=>site_url('/#contact'),'visible'=>true,'sort'=>40,'page_slug'=>'']];$a=read_json('tabs.json',$d);usort($a,fn($x,$y)=>($x['sort']??0)<=>($y['sort']??0));return $a;}function custom_pages():array{return read_json('pages.json',[]);}function custom_page_by_slug(string $slug):?array{foreach(custom_pages() as $p)if(($p['slug']??'')===$slug)return $p;return null;}function tab_url(array $tab):string{if(!empty($tab['page_slug']))return site_url('/page.php?slug='.rawurlencode((string)$tab['page_slug']));return (string)($tab['url']??site_url('/'));}function safe_page_html(string $html):string{$allowed='<p><br><strong><b><em><i><u><h2><h3><h4><ul><ol><li><blockquote><a><hr>';$html=strip_tags($html,$allowed);$html=preg_replace('/\s+on\w+\s*=\s*(["\']).*?\1/is','',$html);return preg_replace('/javascript\s*:/i','',$html);}function projects():array{return array_reverse(read_json('projects.json',[]));}function project_by_slug(string $s):?array{foreach(projects() as $p)if(($p['slug']??'')===$s)return $p;return null;}
function save_uploaded_images(array $f):array{$out=[];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($f['tmp_name']))return $out;foreach((array)$f['tmp_name'] as $i=>$tmp){if(((array)$f['error'])[$i]!==UPLOAD_ERR_OK||!is_uploaded_file($tmp)||filesize($tmp)>10*1024*1024)continue;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);if(!isset($allowed[$mime]))continue;$n=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(move_uploaded_file($tmp,UPLOAD_PATH.'/'.$n))$out[]=site_url('/uploads/projects/'.$n);}return $out;}function delete_project_image(string $url):void{$path=parse_url($url,PHP_URL_PATH);$file=ROOT_PATH.'/'.ltrim((string)$path,'/');if(str_starts_with(realpath(dirname($file))?:'',realpath(UPLOAD_PATH)?:UPLOAD_PATH)&&is_file($file))@unlink($file);}
